const R=(id,en,options,si,se,hi,he)=>Q(B(id,en),options,0,B(si,se),B(hi,he));
const S=(title,theory,formula,example,warning,visual,questions)=>({title,theory,formula,example,warning,visual,questions});
const U=(id,title,desc,prereq,goals,subtopics)=>({id,title,desc,prereq,goals,subtopics,tag:'FURTHER FUNCTIONS / AS–A LEVEL BRIDGE'});
units.push(
U('polynomial',B('Fungsi polinom','Polynomial functions'),B('Dari bentuk aljabar ke akar dan perilaku grafik.','From algebraic structure to roots and graph behaviour.'),B('Kuadrat, faktorisasi, dan substitusi.','Quadratics, factorisation, and substitution.'),B('Mengenali derajat; menggunakan teorema faktor dan sisa; membaca multiplicity.','Identify degree; use factor and remainder theorems; interpret multiplicity.'),[
S(B('Bentuk & derajat','Form & degree'),[
B('Polinom dalam x adalah jumlah berhingga aₙxⁿ+⋯+a₁x+a₀, dengan pangkat bulat tidak negatif dan koefisien real. Derajat adalah pangkat terbesar dengan koefisien bukan nol.','A polynomial in x is a finite sum aₙxⁿ+⋯+a₁x+a₀, with nonnegative integer powers and real coefficients. Its degree is the largest exponent with nonzero coefficient.'),
B('x⁻¹, √x, dan 2ˣ bukan polinom dalam x. Polinom konstan bukan nol berderajat 0; derajat polinom nol tidak didefinisikan di sini.','x⁻¹, √x, and 2ˣ are not polynomials in x. A nonzero constant has degree 0; the zero polynomial has no defined degree here.'),
B('Gabungkan suku sejenis sebelum menentukan derajat. Suku berderajat tertinggi mengendalikan perilaku saat |x| sangat besar; koefisien lain tetap memengaruhi bentuk di dekat akar.','Combine like terms before finding the degree. The leading term controls behaviour for very large |x|; other coefficients still affect the shape near roots.')],
'P(x) = aₙxⁿ + ⋯ + a₁x + a₀, aₙ ≠ 0',
B('P(x)=2x³−x²+4x−7 memiliki derajat 3, koefisien utama 2, dan P(0)=−7. Pada arah kanan grafik naik tanpa batas; pada arah kiri turun tanpa batas.','P(x)=2x³−x²+4x−7 has degree 3, leading coefficient 2, and P(0)=−7. The graph tends upward to the right and downward to the left.'),
B('Derajat ditentukan setelah penyederhanaan, bukan sekadar membaca suku pertama.','Find the degree after simplifying, rather than just reading the first term.'),
B('Ubah multiplicity m. Amati derajat dan perilaku di dekat akar x=1; hitung nilai pada titik uji t.','Change multiplicity m. Observe the degree and behaviour near x=1; evaluate at a test input t.'),[
R('Derajat 5x⁴−3x²+1 adalah…','The degree of 5x⁴−3x²+1 is…',['4','5','2','1'],['Pangkat tertinggi dengan koefisien bukan nol adalah 4.','Koefisien 5 tidak menentukan derajat.'],['The highest power with nonzero coefficient is 4.','The coefficient 5 does not determine the degree.'],'Bedakan pangkat dan koefisien.','Distinguish exponents from coefficients.'),
R('Manakah polinom dalam x?','Which is a polynomial in x?',['3x²−√2 x+1','x⁻¹+2','√x+1','2ˣ+1'],['Koefisien boleh irasional, seperti √2.','Pada pilihan pertama semua pangkat x adalah bilangan bulat tidak negatif.'],['Coefficients may be irrational, such as √2.','In the first option all powers of x are nonnegative integers.'],'Akar pada koefisien berbeda dari akar pada variabel.','A square root in a coefficient differs from a square root of the variable.'),
R('Derajat (x+1)³−x³−3x² adalah…','Find the degree of (x+1)³−x³−3x².',['1','3','2','0'],['(x+1)³=x³+3x²+3x+1.','Setelah pengurangan tersisa 3x+1, berderajat 1.'],['(x+1)³=x³+3x²+3x+1.','Subtracting leaves 3x+1, which has degree 1.'],'Suku berderajat tertinggi dapat saling menghapus.','Leading terms can cancel.')]),
S(B('Faktor & sisa','Factors & remainders'),[
B('Algoritma pembagian: P(x)=(x−a)Q(x)+r. Karena pembagi berderajat 1, sisanya konstanta. Substitusi x=a memberikan r=P(a).','The division algorithm gives P(x)=(x−a)Q(x)+r. Since the divisor has degree 1, the remainder is constant. Substituting x=a gives r=P(a).'),
B('Teorema faktor: x−a faktor P jika dan hanya jika P(a)=0. Setelah menemukan satu faktor, bagi atau cocokkan koefisien untuk mencari faktor lain.','The factor theorem: x−a is a factor of P if and only if P(a)=0. After finding a factor, divide or compare coefficients to find the others.'),
B('Untuk pembagi bx−c dengan b≠0, gunakan x=c/b untuk menghitung sisa. Sisa nol tetap menandakan pembagian tepat.','For divisor bx−c with b≠0, substitute x=c/b to find the remainder. A zero remainder means exact division.')],
'P(x) = (x−a)Q(x) + P(a)',
B('P(x)=x³−2x²−5x+6. P(1)=0, sehingga x−1 faktor. Pembagian memberi x²−x−6=(x−3)(x+2). Jadi P=(x−1)(x−3)(x+2).','P(x)=x³−2x²−5x+6. P(1)=0, so x−1 is a factor. Division gives x²−x−6=(x−3)(x+2). Hence P=(x−1)(x−3)(x+2).'),
B('Untuk faktor x+2, uji P(−2), bukan P(2).','For a factor x+2, test P(−2), not P(2).'),
B('Titik uji menunjukkan P(t): nilainya sama dengan sisa pembagian oleh x−t.','The test point shows P(t): this equals the remainder on division by x−t.'),[
R('Sisa pembagian x³+2x−1 oleh x−2 adalah…','Find the remainder when x³+2x−1 is divided by x−2.',['11','7','3','0'],['Sisa=P(2).','P(2)=8+4−1=11.'],['The remainder is P(2).','P(2)=8+4−1=11.'],'Substitusi akar pembagi.','Substitute the zero of the divisor.'),
R('Jika x+1 faktor x³+kx+2, tentukan k.','If x+1 is a factor of x³+kx+2, find k.',['1','−1','3','−3'],['P(−1)=−1−k+2=0.','1−k=0, sehingga k=1.'],['P(−1)=−1−k+2=0.','1−k=0, so k=1.'],'Faktor memberi syarat sisa nol.','A factor gives a zero-remainder condition.'),
R('Sisa pembagian 4x³−x+1 oleh 2x−1 adalah…','Find the remainder when 4x³−x+1 is divided by 2x−1.',['1','4','0','1/2'],['Akar pembagi adalah x=1/2.','P(1/2)=4(1/8)−1/2+1=1.'],['The divisor vanishes at x=1/2.','P(1/2)=4(1/8)−1/2+1=1.'],'Pembagi tidak harus berbentuk x−a dengan koefisien x=1.','The coefficient of x in the divisor need not be 1.')]),
S(B('Akar & multiplicity','Roots & multiplicity'),[
B('Jika P(x)=(x−a)ᵐQ(x), Q(a)≠0, maka a adalah akar dengan multiplicity m. Faktor genap tidak mengubah tanda saat melewati a; faktor ganjil mengubah tanda.','If P(x)=(x−a)ᵐQ(x), Q(a)≠0, then a is a root of multiplicity m. An even power does not change sign across a; an odd power does.'),
B('Multiplicity genap: grafik menyentuh sumbu-x dan berbalik secara lokal. Multiplicity ganjil: grafik melintasinya, termasuk bentuk melandai untuk m=3.','Even multiplicity: the graph touches the x-axis and turns locally. Odd multiplicity: it crosses, including a flattened crossing when m=3.'),
B('Untuk menyelesaikan pertidaksamaan polinom, susun akar berurutan dan uji tanda pada tiap interval. Sertakan akar hanya jika simbol pertidaksamaannya mengizinkan sama dengan.','To solve a polynomial inequality, order the roots and test the sign in each interval. Include roots only when equality is allowed.')],
'P(x) = (x−a)ᵐQ(x), Q(a) ≠ 0',
B('P(x)=(x+2)(x−1)². Akar −2 sederhana melintasi sumbu, akar 1 ganda menyentuhnya. Karena (x−1)²>0 di luar 1, tanda P mengikuti x+2. Jadi P<0 tepat untuk x<−2.','P(x)=(x+2)(x−1)². The simple root −2 crosses the axis; the double root 1 touches it. Since (x−1)²>0 away from 1, the sign follows x+2. Thus P<0 exactly when x<−2.'),
B('Jumlah akar real berbeda dapat lebih kecil daripada derajat polinom.','The number of distinct real roots can be smaller than the degree.'),
B('Bandingkan m=1 dan m=2 pada akar x=1. Faktor 1/4 hanya mengubah tinggi, bukan akar atau multiplicity.','Compare m=1 and m=2 at x=1. The factor 1/4 changes heights, but not roots or multiplicities.'),[
R('Akar x=2 pada (x−2)²(x+1) memiliki multiplicity…','The root x=2 of (x−2)²(x+1) has multiplicity…',['2','1','3','0'],['Faktor x−2 muncul berpangkat 2.','Faktor x+1 tidak nol saat x=2.'],['The factor x−2 is raised to power 2.','The other factor x+1 is nonzero at x=2.'],'Periksa pangkat faktor akar itu.','Check the power of that root factor.'),
R('Solusi (x−1)(x+2)>0 adalah…','Solve (x−1)(x+2)>0.',['x<−2 atau / or x>1','−2<x<1','x>−2','x<1'],['Akar adalah −2 dan 1.','Kedua faktor bertanda sama di luar kedua akar, sehingga hasil kali positif.','Akar tidak termasuk karena >0.'],['The roots are −2 and 1.','The factors have the same sign outside the roots, so the product is positive.','Exclude the roots because the inequality is strict.'],'Uji satu nilai pada setiap interval.','Test one value in each interval.'),
R('Solusi (x+2)(x−1)²≤0 adalah…','Solve (x+2)(x−1)²≤0.',['(−∞,−2] ∪ {1}','[−2,1]','(−∞,−2]','ℝ'],['Untuk x≠1, faktor kuadrat positif sehingga perlu x+2≤0, yaitu x≤−2.','Pada x=1 hasil kali juga nol; tambahkan titik terisolasi itu.'],['For x≠1, the square is positive, so x+2≤0, giving x≤−2.','At x=1 the product is also zero; include that isolated point.'],'Akar genap dapat memberi solusi terisolasi pada ≤0.','An even root can give an isolated solution of a ≤0 inequality.')])]),
U('rational',B('Fungsi rasional','Rational functions'),B('Pembatasan, asimtot, dan lubang yang tidak boleh hilang.','Restrictions, asymptotes, and holes that must stay excluded.'),B('Faktorisasi polinom dan persamaan pecahan.','Polynomial factorisation and fractional equations.'),B('Menjaga domain saat menyederhanakan; membedakan lubang dan asimtot; memeriksa solusi.','Preserve domain during simplification; distinguish holes from asymptotes; check solutions.'),[
S(B('Domain & lubang','Domain & holes'),[
B('Fungsi rasional berbentuk P(x)/Q(x), dengan P,Q polinom dan Q bukan polinom nol. Domain real alaminya mengeluarkan setiap akar Q.','A rational function is P(x)/Q(x), where P,Q are polynomials and Q is not the zero polynomial. Its natural real domain excludes every zero of Q.'),
B('Faktor yang dicoret tidak mengembalikan input yang semula dilarang. Jika faktor penyebab penyebut nol hilang sepenuhnya setelah penyederhanaan, grafik memiliki lubang pada titik itu.','Cancelling a factor does not restore originally excluded inputs. If the factor causing the zero denominator disappears completely after simplification, the graph has a hole there.'),
B('Jika setelah penyederhanaan masih ada faktor penyebut nol dan pembilang tidak nol di a, x=a adalah asimtot vertikal. Lubang ditandai lingkaran kosong, bukan titik penuh.','If a denominator factor remains after simplification and the numerator is nonzero at a, x=a is a vertical asymptote. Mark a hole with an open circle, not a filled point.')],
'(x²−1)/(x−1) = x+1, only for x ≠ 1',
B('f(x)=(x²−1)/(x−1). Untuk x≠1, f(x)=x+1. Grafik berupa garis dengan lubang di (1,2). Domain ℝ∖{1}, range ℝ∖{2}.','f(x)=(x²−1)/(x−1). For x≠1, f(x)=x+1. Its graph is a line with a hole at (1,2). Domain ℝ∖{1}, range ℝ∖{2}.'),
B('Pencoretan berlaku pada faktor hasil kali, bukan suku dalam penjumlahan.','Cancel multiplicative factors, not terms in a sum.'),
B('Bandingkan lubang dan asimtot. Titik kosong tetap dikeluarkan walaupun rumus yang disederhanakan tampak terdefinisi.','Compare a hole and an asymptote. The open point remains excluded even when the simplified rule looks defined.'),[
R('Domain (x+1)/(x−3) adalah…','Find the domain of (x+1)/(x−3).',['ℝ ∖ {3}','ℝ ∖ {−1}','ℝ','[3,∞)'],['Penyebut nol saat x=3.','Pembilang boleh nol; hanya x=3 harus dikeluarkan.'],['The denominator is zero at x=3.','The numerator may be zero; only x=3 must be excluded.'],'Larangan berasal dari penyebut.','The restriction comes from the denominator.'),
R('Lubang grafik (x²−4)/(x−2) terletak di…','Where is the hole in (x²−4)/(x−2)?',['(2,4)','(2,0)','(−2,0)','(4,2)'],['Faktorkan: (x−2)(x+2)/(x−2)=x+2, x≠2.','Pada x=2, perpanjangan garis memiliki y=4; titik (2,4) dikeluarkan.'],['Factor: (x−2)(x+2)/(x−2)=x+2, x≠2.','At x=2, the extended line has y=4; the point (2,4) is excluded.'],'Koordinat lubang dibaca dari rumus setelah penyederhanaan.','Use the simplified rule to find the hole height.'),
R('Domain dan range f(x)=(x²−1)/(x−1) adalah…','Find the domain and range of f(x)=(x²−1)/(x−1).',[B('D=ℝ∖{1}, R=ℝ∖{2}','D=ℝ∖{1}, R=ℝ∖{2}'),'D=ℝ, R=ℝ','D=ℝ∖{1}, R=ℝ','D=ℝ∖{2}, R=ℝ∖{1}'],['f(x)=x+1 hanya untuk x≠1.','y=2 memerlukan x=1, yang dilarang. Semua y≠2 memberi x=y−1≠1.'],['f(x)=x+1 only for x≠1.','y=2 requires the forbidden input x=1. Every y≠2 gives x=y−1≠1.'],'Satu input yang hilang dapat menghilangkan satu output.','A missing input may remove an output.')]),
S(B('Asimtot & persamaan','Asymptotes & equations'),[
B('Asimtot adalah garis yang didekati grafik pada perilaku limit tertentu. Untuk f(x)=k/(x−h)+v dengan k≠0: x=h vertikal dan y=v horizontal. Domain mengeluarkan h; range mengeluarkan v.','An asymptote is a line approached in a limiting behaviour. For f(x)=k/(x−h)+v with k≠0: x=h is vertical and y=v horizontal. The domain excludes h; the range excludes v.'),
B('Secara umum, bandingkan derajat pembilang dan penyebut setelah penyederhanaan: derajat pembilang lebih kecil → asimtot y=0; sama → rasio koefisien utama. Jika selisih derajat 1, pembagian menghasilkan asimtot miring.','More generally, compare degrees after simplification: smaller numerator degree → horizontal asymptote y=0; equal degrees → ratio of leading coefficients. A degree difference of 1 gives an oblique asymptote by division.'),
B('Sebelum mengalikan persamaan dengan penyebut, catat nilai yang dilarang. Selesaikan, lalu substitusi calon solusi ke persamaan semula.','Before multiplying an equation by denominators, record excluded inputs. Solve, then substitute candidates into the original equation.')],
'f(x) = k/(x−h) + v, k ≠ 0',
B('(x+1)/(x−1)=3, x≠1. Kalikan: x+1=3x−3, jadi x=2. Cek: 3/1=3. Untuk grafik, (x+1)/(x−1)=1+2/(x−1), sehingga asimtot x=1 dan y=1.','(x+1)/(x−1)=3, x≠1. Multiply: x+1=3x−3, so x=2. Check: 3/1=3. For the graph, (x+1)/(x−1)=1+2/(x−1), giving asymptotes x=1 and y=1.'),
B('Tidak semua nol penyebut adalah asimtot setelah faktor bersama diperhitungkan.','Not every denominator zero is an asymptote once common factors are considered.'),
B('Ubah h dan v pada 1/(x−h)+v. Asimtot digambar putus-putus; kedua cabang tidak dihubungkan melewati singularitas.','Change h and v in 1/(x−h)+v. Dashed lines mark asymptotes; the two branches are not joined across the singularity.'),[
R('Asimtot horizontal 3/(x−2)+4 adalah…','The horizontal asymptote of 3/(x−2)+4 is…',['y=4','x=2','y=0','x=4'],['Saat |x| besar, 3/(x−2) mendekati 0.','Maka fungsi mendekati y=4.'],['As |x| becomes large, 3/(x−2) tends to 0.','Hence the function approaches y=4.'],'Asimtot horizontal berbentuk y=konstanta.','A horizontal asymptote has the form y=constant.'),
R('Selesaikan 2/(x−1)=1, x≠1.','Solve 2/(x−1)=1, x≠1.',['x=3','x=1','x=−1','x=2'],['Kalikan dengan x−1 yang bukan nol: 2=x−1.','x=3; cek 2/(3−1)=1.'],['Multiply by the nonzero x−1: 2=x−1.','x=3; check 2/(3−1)=1.'],'Tetap periksa larangan domain.','Keep the domain restriction.'),
R('Solusi (x²−1)/(x−1)=2 adalah…','Solve (x²−1)/(x−1)=2.',[B('Tidak ada solusi','No solution'),'x=1','x=−1','x=3'],['Domain mensyaratkan x≠1. Rumus menjadi x+1=2.','Calon x=1 dilarang; jadi tidak ada solusi.'],['The domain requires x≠1. The equation simplifies to x+1=2.','The candidate x=1 is excluded, so there is no solution.'],'Menyederhanakan persamaan tidak menghapus larangan awal.','Simplification does not remove the original restriction.')])]),
U('modulus',B('Fungsi modulus','Modulus functions'),B('Nilai mutlak sebagai jarak.','Absolute value as distance.'),B('Pertidaksamaan dan grafik linear.','Inequalities and linear graphs.'),B('Menyelesaikan persamaan dan pertidaksamaan modulus dengan interpretasi jarak.','Solve modulus equations and inequalities using distance.'),[
S(B('Jarak & persamaan','Distance & equations'),[
B('|x| adalah jarak x dari 0 pada garis bilangan. Jadi |x|=x untuk x≥0 dan |x|=−x untuk x<0. Nilainya selalu tidak negatif.','|x| is the distance of x from 0 on the number line. Thus |x|=x for x≥0 and |x|=−x for x<0. It is always nonnegative.'),
B('|x−h| adalah jarak dari h. Untuk c>0, persamaan |x−h|=c memberi x=h−c atau h+c. Untuk c=0 hanya x=h; untuk c<0 tidak ada solusi.','|x−h| is distance from h. For c>0, |x−h|=c gives x=h−c or h+c. For c=0 only x=h; for c<0 there is no solution.'),
B('Grafik y=|x−h|+k berbentuk V dengan puncak (h,k). Domain ℝ, range [k,∞).','The graph y=|x−h|+k is V-shaped with vertex (h,k). Its domain is ℝ and range [k,∞).')],
'|x−h| = c ⇔ x=h−c or x=h+c (c≥0)',
B('|2x−3|=5: 2x−3=5 atau 2x−3=−5. Maka x=4 atau x=−1. Kedua nilai memberi nilai mutlak 5.','|2x−3|=5: 2x−3=5 or 2x−3=−5. Thus x=4 or x=−1. Both give absolute value 5.'),
B('√(x²)=|x|, bukan selalu x.','√(x²)=|x|, not always x.'),
B('Ubah h, lalu pilih c. Garis horizontal y=c berpotongan dengan y=|x−h| pada dua batas jarak.','Change h, then c. The horizontal line y=c meets y=|x−h| at the two distance boundaries.'),[
R('Hitung |−7|.','Evaluate |−7|.',['7','−7','0','±7'],['Jarak −7 dari nol adalah 7.','Nilai mutlak menghasilkan satu nilai tidak negatif.'],['The distance from −7 to zero is 7.','Absolute value gives one nonnegative value.'],'Jarak tidak negatif.','Distance is nonnegative.'),
R('Selesaikan |x−2|=3.','Solve |x−2|=3.',['x=−1, 5','x=1, 5','x=−5, 1','x=5'],['Jarak x dari 2 adalah 3.','x=2−3=−1 atau x=2+3=5.'],['The distance from x to 2 is 3.','x=2−3=−1 or x=2+3=5.'],'Ada dua sisi dari pusat.','There are two sides of the centre.'),
R('Selesaikan |2x−1|=x+2.','Solve |2x−1|=x+2.',['x=−1/3, 3','x=3','x=−3, 1/3','x=−2, 3'],['Harus x+2≥0. Cabang 2x−1≥0 memberi 2x−1=x+2 → x=3.','Cabang 2x−1<0 memberi −2x+1=x+2 → x=−1/3.','Keduanya memenuhi syarat cabang dan persamaan asli.'],['Require x+2≥0. The branch 2x−1≥0 gives 2x−1=x+2 → x=3.','The branch 2x−1<0 gives −2x+1=x+2 → x=−1/3.','Both meet their branch conditions and the original equation.'],'Periksa syarat tiap cabang.','Check each branch condition.')]),
S(B('Pertidaksamaan modulus','Modulus inequalities'),[
B('Untuk c>0, |x−h|<c berarti jaraknya kurang dari c: h−c<x<h+c. Ini interval di antara dua batas.','For c>0, |x−h|<c means distance less than c: h−c<x<h+c. This is the interval between the boundaries.'),
B('Untuk c>0, |x−h|>c berarti di luar: x<h−c atau x>h+c. Simbol ≤ atau ≥ menyertakan titik batas.','For c>0, |x−h|>c means outside: x<h−c or x>h+c. The symbols ≤ or ≥ include the boundary points.'),
B('Untuk membandingkan dua nilai mutlak, kedua sisi tidak negatif sehingga boleh dikuadratkan tanpa mengubah kesetaraan pertidaksamaan. Tetap selesaikan tanda hasil akhirnya.','To compare two absolute values, both sides are nonnegative, so squaring preserves the inequality. Still solve the resulting sign condition.')],
'|x−h| < c ⇔ h−c < x < h+c (c>0)',
B('|2x+1|≤5 → −5≤2x+1≤5 → −6≤2x≤4 → −3≤x≤2.','|2x+1|≤5 → −5≤2x+1≤5 → −6≤2x≤4 → −3≤x≤2.'),
B('“Di luar” memakai atau, bukan dan.','“Outside” uses or, not and.'),
B('Bagian V di bawah garis y=c sesuai interval |x−h|<c; kedua titik potong adalah batasnya.','The part of the V below y=c corresponds to |x−h|<c; the intersections give its boundaries.'),[
R('Selesaikan |x|<4.','Solve |x|<4.',['−4<x<4','x<−4 atau / or x>4','x<4','−4≤x≤4'],['Jarak dari 0 kurang dari 4.','Maka x berada ketat di antara −4 dan 4.'],['The distance from 0 is less than 4.','Thus x lies strictly between −4 and 4.'],'Perhatikan batas ketat.','Watch the strict boundaries.'),
R('Selesaikan |x−1|≥2.','Solve |x−1|≥2.',['x≤−1 atau / or x≥3','−1≤x≤3','x≥−1','x≤3'],['Jarak dari 1 minimal 2.','Batasnya 1−2=−1 dan 1+2=3; ambil bagian luar beserta batas.'],['The distance from 1 is at least 2.','The boundaries are −1 and 3; take the outside regions including endpoints.'],'≥ berarti di luar termasuk batas.','≥ means outside, including boundaries.'),
R('Selesaikan |x−1|<|x+2|.','Solve |x−1|<|x+2|.',['x>−1/2','x<−1/2','x>1/2','−2<x<1'],['Kedua sisi tidak negatif: kuadratkan menjadi (x−1)²<(x+2)².','x²−2x+1<x²+4x+4 → −3<6x → x>−1/2.','Ini titik-titik yang lebih dekat ke 1 daripada ke −2.'],['Both sides are nonnegative: square to get (x−1)²<(x+2)².','x²−2x+1<x²+4x+4 → −3<6x → x>−1/2.','These points are closer to 1 than to −2.'],'Batasnya titik tengah dua pusat.','The boundary is the midpoint of the two centres.')])]),
U('piecewise',B('Fungsi potongan','Piecewise functions'),B('Aturan berbeda, domain yang jelas.','Different rules, clearly defined domains.'),B('Notasi fungsi dan interval.','Function notation and intervals.'),B('Memilih cabang yang benar dan memeriksa batas serta kontinuitas.','Select the correct branch and inspect boundaries and continuity.'),[
S(B('Cabang & titik batas','Branches & endpoints'),[
B('Fungsi potongan memakai rumus berbeda pada bagian domain yang berbeda. Pilih cabang berdasarkan input, baru substitusikan ke rumus cabang itu.','A piecewise function uses different formulas on different parts of its domain. Choose the branch using the input, then substitute into that branch rule.'),
B('Lingkaran penuh berarti titik termasuk; lingkaran kosong berarti tidak termasuk. Pada batas, simbol < dan ≤ menentukan nilai fungsi yang sebenarnya.','A filled circle means the point is included; an open circle means it is excluded. At a boundary, < and ≤ determine the actual function value.'),
B('Untuk mendefinisikan fungsi pada seluruh domain yang dimaksud, jangan tinggalkan celah input atau berikan dua output berbeda untuk input yang sama.','To define a function on the intended full domain, avoid gaps in inputs and avoid assigning two different outputs to the same input.')],
'f(x) = x+1 for x<0; x²+c for x≥0',
B('Dengan c=2: f(−2)=−2+1=−1, f(0)=0²+2=2, dan f(3)=9+2=11. Di x=0, cabang kanan menentukan f(0).','With c=2: f(−2)=−2+1=−1, f(0)=0²+2=2, and f(3)=9+2=11. At x=0, the right branch defines f(0).'),
B('Jangan memilih cabang berdasarkan nilai output yang diharapkan.','Do not select a branch based on the output you expect.'),
B('Ubah c dan titik uji. Titik kosong di (0,1) adalah batas kiri, sedangkan titik penuh (0,c) adalah nilai fungsi.','Vary c and the test input. The open point (0,1) marks the left boundary, while the filled point (0,c) is the function value.'),[
R('f(x)=x+1 untuk x<0; x²+2 untuk x≥0. Berapa f(0)?','f(x)=x+1 for x<0; x²+2 for x≥0. Find f(0).',['2','1','0','−1'],['Input 0 memenuhi x≥0.','Gunakan x²+2: f(0)=2.'],['The input 0 satisfies x≥0.','Use x²+2: f(0)=2.'],'Tanda sama dengan menentukan cabang di batas.','The equality sign selects the branch at a boundary.'),
R('Untuk fungsi yang sama, hitung f(−2)+f(2).','For the same function, find f(−2)+f(2).',['5','3','7','9'],['f(−2)=−2+1=−1 dari cabang kiri.','f(2)=4+2=6 dari cabang kanan. Jumlahnya 5.'],['f(−2)=−2+1=−1 from the left branch.','f(2)=4+2=6 from the right branch. The sum is 5.'],'Dua input dapat memakai cabang berbeda.','Two inputs may use different branches.'),
R('Range f(x)=x+1 untuk x<0; x²+2 untuk x≥0 adalah…','Find the range of f(x)=x+1 for x<0; x²+2 for x≥0.',['(−∞,1) ∪ [2,∞)','ℝ','(−∞,1] ∪ [2,∞)','[1,∞)'],['Cabang kiri menghasilkan semua y<1, tetapi bukan 1.','Cabang kanan menghasilkan y≥2. Gabungkan kedua himpunan.'],['The left branch gives all y<1, but not 1.','The right branch gives y≥2. Take the union.'],'Range kedua cabang digabung, bukan diisi celahnya.','Take the union of the branch ranges; do not fill the gap.')]),
S(B('Mencocokkan di batas','Matching at a boundary'),[
B('Kontinu di x=a berarti nilai yang didekati dari kedua sisi sama dengan nilai fungsi di a. Grafik dapat dilalui tanpa lompatan di titik itu.','Continuity at x=a means both one-sided limiting values agree with the function value at a. There is no jump there.'),
B('Untuk cabang polinom yang bertemu di a, substitusi a ke rumus kiri dan kanan untuk mencocokkan nilai batas. Nilai fungsi tetap mengikuti cabang yang menyertakan a.','For polynomial branches meeting at a, substitute a into each branch rule to match the boundary values. The actual function value still comes from the branch including a.'),
B('Kontinu tidak berarti mulus: y=|x| kontinu di 0 tetapi memiliki sudut. Mencocokkan nilai saja tidak menjamin gradien kiri dan kanan sama.','Continuous does not mean smooth: y=|x| is continuous at 0 but has a corner. Matching values does not guarantee matching one-sided gradients.')],
'left boundary value = f(a) = right boundary value',
B('f=x+1 untuk x<0 dan f=x²+c untuk x≥0. Batas kiri 1 dan f(0)=c. Kontinuitas memerlukan c=1. Gradien kiri 1, kanan 0, jadi tetap ada sudut.','f=x+1 for x<0 and f=x²+c for x≥0. The left boundary value is 1 and f(0)=c. Continuity requires c=1. Left and right gradients are 1 and 0, so a corner remains.'),
B('Titik penuh di batas tidak otomatis menyambungkan grafik.','A filled endpoint alone does not make the graph continuous.'),
B('Cari nilai c yang menghilangkan lompatan. Lingkaran kosong dan penuh berimpit saat c=1.','Find the c that removes the jump. The open and filled boundary points coincide when c=1.'),[
R('Agar x+1 (x<0) dan x²+c (x≥0) kontinu di 0, c=…','To make x+1 (x<0) and x²+c (x≥0) continuous at 0, c=…',['1','0','−1','2'],['Batas kiri adalah 0+1=1.','Nilai dan batas kanan adalah c; maka c=1.'],['The left boundary value is 0+1=1.','The function value and right boundary value are c; hence c=1.'],'Cocokkan tinggi kedua cabang.','Match the heights of the branches.'),
R('f(x)=2x+k untuk x<1; x²+3 untuk x≥1. Nilai k agar kontinu adalah…','f(x)=2x+k for x<1; x²+3 for x≥1. Find k for continuity.',['2','3','4','1'],['Batas kiri di 1 adalah 2+k.','Nilai kanan adalah 1+3=4; jadi 2+k=4 dan k=2.'],['The left boundary value at 1 is 2+k.','The right value is 1+3=4; hence 2+k=4, so k=2.'],'Substitusikan titik pertemuan, bukan nol.','Substitute the joining input, not zero.'),
R('Jika kedua cabang x+1 (x<0) dan x²+1 (x≥0) kontinu di 0, apakah gradien juga cocok?','For the continuous branches x+1 (x<0) and x²+1 (x≥0), do the gradients match at 0?',[B('Tidak: kiri 1, kanan 0','No: left 1, right 0'),B('Ya: keduanya 1','Yes: both 1'),B('Ya: keduanya 0','Yes: both 0'),B('Fungsi tidak kontinu','The function is not continuous')],['Nilai batas kedua cabang sama-sama 1.','Gradien cabang kiri adalah 1; cabang kanan memiliki gradien 2x, yaitu 0 di batas. Jadi kontinu tetapi tidak terdiferensialkan di 0.'],['Both boundary values equal 1.','The left branch has gradient 1; the right has gradient 2x, which is 0 at the boundary. The function is continuous but not differentiable at 0.'],'Kesamaan nilai dan kesamaan gradien adalah dua syarat berbeda.','Matching values and matching gradients are different conditions.')])])
);
units.push(
U('transform',B('Transformasi grafik','Graph transformations'),B('Lacak titik, bukan hafalkan tanda saja.','Track points, rather than just memorising signs.'),B('Grafik fungsi dasar dan koordinat.','Basic function graphs and coordinates.'),B('Menghubungkan perubahan rumus dengan perpindahan koordinat dan perubahan skala.','Connect formula changes to coordinate shifts and scaling.'),[
S(B('Translasi & refleksi','Translations & reflections'),[
B('Jika (u,v) berada pada y=f(x), maka pada y=f(x−h)+k titiknya menjadi (u+h,v+k). Pergeseran horizontal mengubah input; pergeseran vertikal mengubah output.','If (u,v) lies on y=f(x), then on y=f(x−h)+k it becomes (u+h,v+k). A horizontal translation changes the input; a vertical translation changes the output.'),
B('y=−f(x) merefleksikan grafik terhadap sumbu-x: (u,v)→(u,−v). y=f(−x) merefleksikan terhadap sumbu-y: (u,v)→(−u,v).','y=−f(x) reflects in the x-axis: (u,v)→(u,−v). y=f(−x) reflects in the y-axis: (u,v)→(−u,v).'),
B('Perubahan domain mengikuti koordinat x yang baru; range mengikuti koordinat y yang baru. Pada gabungan transformasi, tulis rumus akhir agar urutannya tidak ambigu.','The domain follows the new x-coordinates; the range follows the new y-coordinates. For combined transformations, write the final formula to remove ambiguity about order.')],
'(u,v) on f → (u+h,v+k) on f(x−h)+k',
B('Titik (2,5) pada f berpindah ke (5,3) pada g(x)=f(x−3)−2. Alasannya: agar input ke f tetap 2, x harus 5, lalu output dikurangi 2.','The point (2,5) on f moves to (5,3) on g(x)=f(x−3)−2. To feed 2 into f, x must be 5; the output is then reduced by 2.'),
B('f(x+3) bergeser ke kiri 3, bukan ke kanan.','f(x+3) shifts left by 3, not right.'),
B('Gunakan grafik dasar f(x)=|x|. Lacak satu titik dasar dan bayangannya pada grafik hasil transformasi.','Use the base graph f(x)=|x|. Track a base point and its image on the transformed graph.'),[
R('y=f(x)+4 menggeser grafik…','y=f(x)+4 translates the graph…',[B('ke atas 4','up by 4'),B('ke kanan 4','right by 4'),B('ke kiri 4','left by 4'),B('ke bawah 4','down by 4')],['Input tidak berubah.','Setiap output bertambah 4 sehingga semua titik naik 4.'],['The input stays the same.','Every output increases by 4, so each point moves up by 4.'],'Perubahan di luar f mengubah output.','A change outside f acts on the output.'),
R('Titik (−1,3) pada f menjadi titik apa pada g(x)=f(x+2)−5?','Where does (−1,3) on f move on g(x)=f(x+2)−5?',['(−3,−2)','(1,−2)','(−3,8)','(1,8)'],['x+2=−1 memberi x=−3.','Output 3−5=−2; jadi (−3,−2).'],['x+2=−1 gives x=−3.','The output is 3−5=−2, giving (−3,−2).'],'Pertahankan input asli di dalam f.','Keep the original input inside f.'),
R('Jika domain f=[1,4] dan range f=[−2,3], tentukan domain dan range g(x)=−f(x−2)+1.','If f has domain [1,4] and range [−2,3], find the domain and range of g(x)=−f(x−2)+1.',['D=[3,6], R=[−2,3]','D=[−1,2], R=[−2,3]','D=[3,6], R=[−1,4]','D=[1,4], R=[−2,3]'],['Syarat x−2∈[1,4] memberi x∈[3,6].','Output v berubah menjadi 1−v. Ujung v=−2 dan 3 menjadi 3 dan −2, jadi range [−2,3].'],['Require x−2∈[1,4], giving x∈[3,6].','An output v becomes 1−v. Endpoints −2 and 3 become 3 and −2, so the range is [−2,3].'],'Refleksi membalik urutan batas output.','Reflection reverses the order of output bounds.')]),
S(B('Peregangan & gabungan','Stretches & combinations'),[
B('Untuk g(x)=a f(b(x−h))+k, dengan a,b≠0, titik (u,v) pada f menjadi (h+u/b, k+av). Rumus koordinat ini menggabungkan semua transformasi secara tepat.','For g(x)=a f(b(x−h))+k, with a,b≠0, a point (u,v) on f becomes (h+u/b, k+av). This coordinate rule combines all transformations exactly.'),
B('|a| adalah faktor skala vertikal; a<0 menambahkan refleksi terhadap sumbu-x sebelum translasi vertikal. Faktor skala horizontal adalah 1/|b|; b<0 memberi refleksi horizontal sebelum translasi horizontal.','|a| is the vertical scale factor; a<0 adds reflection in the x-axis before vertical translation. The horizontal scale factor is 1/|b|; b<0 adds horizontal reflection before horizontal translation.'),
B('Transformasi tidak selalu dapat ditukar urutannya. Misalnya 2(f(x)+1)=2f(x)+2 berbeda dari 2f(x)+1. Periksa titik dan rumus akhir.','Transformations do not always commute. For example, 2(f(x)+1)=2f(x)+2 differs from 2f(x)+1. Check a point and the final formula.')],
'(u,v) → (h+u/b, k+av)',
B('Untuk g(x)=−2f(3(x−1))+4, titik (6,5) menjadi (1+6/3,4−2×5)=(3,−6). Faktor horizontal 1/3 dan vertikal 2, dengan refleksi vertikal.','For g(x)=−2f(3(x−1))+4, the point (6,5) becomes (1+6/3,4−2×5)=(3,−6). The horizontal scale factor is 1/3 and vertical factor 2, with vertical reflection.'),
B('Pada f(2x), faktor skala horizontal adalah 1/2.','For f(2x), the horizontal scale factor is 1/2.'),
B('Ubah a, b, h, k untuk y=a|b(x−h)|+k. Titik berlabel di panel mengikuti rumus koordinat umum.','Vary a, b, h, k for y=a|b(x−h)|+k. The point in the panel follows the general coordinate rule.'),[
R('Faktor skala horizontal pada y=f(3x) adalah…','The horizontal scale factor in y=f(3x) is…',['1/3','3','−3','1'],['Input lama u dicapai saat 3x=u.','Maka x=u/3: koordinat horizontal dibagi 3.'],['An old input u is reached when 3x=u.','Hence x=u/3: horizontal coordinates are divided by 3.'],'Skala input bekerja secara kebalikan pada koordinat.','Input scaling acts reciprocally on coordinates.'),
R('Titik (4,−2) pada f menjadi apa pada g(x)=−3f(2x)+1?','Where does (4,−2) on f move on g(x)=−3f(2x)+1?',['(2,7)','(8,7)','(2,−5)','(8,−5)'],['2x=4 → x=2.','Output −3(−2)+1=7. Jadi titiknya (2,7).'],['2x=4 → x=2.','The output is −3(−2)+1=7, giving (2,7).'],'Hitung koordinat x dan y secara terpisah.','Compute x- and y-coordinates separately.'),
R('Titik (6,5) pada f menjadi apa pada g(x)=−2f(3(x−1))+4?','Where does (6,5) on f move on g(x)=−2f(3(x−1))+4?',['(3,−6)','(19,−6)','(1,−6)','(3,−2)'],['Selesaikan 3(x−1)=6 → x=3.','Output −2×5+4=−6. Maka (3,−6).'],['Solve 3(x−1)=6 → x=3.','The output is −2×5+4=−6, giving (3,−6).'],'Terapkan rumus x=h+u/b.','Use x=h+u/b.')])]),
U('exponential',B('Fungsi eksponen','Exponential functions'),B('Faktor pengali yang tetap.','A constant multiplicative factor.'),B('Pangkat, pecahan, dan persamaan.','Powers, fractions, and equations.'),B('Menggunakan hukum indeks; membaca pertumbuhan dan peluruhan; menyelesaikan persamaan eksponen.','Use index laws; read growth and decay; solve exponential equations.'),[
S(B('Hukum pangkat','Index laws'),[
B('Untuk a>0: aᵖaᑫ=aᵖ⁺ᑫ, aᵖ/aᑫ=aᵖ⁻ᑫ, dan (aᵖ)ᑫ=aᵖᑫ. Pangkat nol memberi 1; pangkat negatif berarti kebalikan.','For a>0: aᵖaᑫ=aᵖ⁺ᑫ, aᵖ/aᑫ=aᵖ⁻ᑫ, and (aᵖ)ᑫ=aᵖᑫ. A zero exponent gives 1; a negative exponent means a reciprocal.'),
B('Untuk a>0 dan n bilangan bulat positif, a^(m/n)=(ⁿ√a)ᵐ. Pembatasan basis positif memudahkan aturan untuk seluruh pangkat real.','For a>0 and positive integer n, a^(m/n)=(ⁿ√a)ᵐ. Restricting to positive bases makes the laws work throughout real exponents.'),
B('Hukum perkalian pangkat tidak berlaku untuk penjumlahan: aᵖ+aᑫ umumnya bukan aᵖ⁺ᑫ.','The multiplication law does not apply to addition: aᵖ+aᑫ is generally not aᵖ⁺ᑫ.')],
'aᵖaᑫ = aᵖ⁺ᑫ; (aᵖ)ᑫ = aᵖᑫ; a⁻ᵖ = 1/aᵖ',
B('16^(3/4)=(⁴√16)³=2³=8. Lalu 2³×2⁻⁵=2⁻²=1/4.','16^(3/4)=(⁴√16)³=2³=8. Also 2³×2⁻⁵=2⁻²=1/4.'),
B('a⁻² bukan −a²; tanda negatif berada pada pangkat.','a⁻² is not −a²; the negative sign belongs to the exponent.'),
B('Pilih basis a lalu geser input x. Panel membandingkan aˣ dan a^(x+1): rasionya selalu a.','Choose a base a and vary x. The panel compares aˣ and a^(x+1): their ratio is always a.'),[
R('Sederhanakan 2³×2⁴.','Simplify 2³×2⁴.',['2⁷','2¹²','4⁷','2'],['Basis sama: jumlahkan pangkat.','2³×2⁴=2^(3+4)=2⁷.'],['With the same base, add the exponents.','2³×2⁴=2^(3+4)=2⁷.'],'Pangkat dijumlahkan untuk perkalian basis sama.','Add exponents when multiplying equal bases.'),
R('Hitung 27^(2/3).','Evaluate 27^(2/3).',['9','18','3','81'],['Akar pangkat tiga 27 adalah 3.','27^(2/3)=3²=9.'],['The cube root of 27 is 3.','27^(2/3)=3²=9.'],'Penyebut pangkat menunjukkan jenis akar.','The denominator of the exponent gives the root.'),
R('Untuk a>0, sederhanakan (a^(3/2) a^(−1/2))²/a³.','For a>0, simplify (a^(3/2) a^(−1/2))²/a³.',['1/a','a','a²','1'],['Di dalam kurung: a^(3/2−1/2)=a.','Kuadratkan lalu bagi: a²/a³=a⁻¹=1/a.'],['Inside the bracket: a^(3/2−1/2)=a.','Square then divide: a²/a³=a⁻¹=1/a.'],'Kerjakan bagian dalam kurung terlebih dahulu.','Work inside the brackets first.')]),
S(B('Grafik & basis','Graphs & bases'),[
B('Fungsi eksponen dasar y=aˣ memakai a>0 dan a≠1. Domain ℝ, range (0,∞); melalui (0,1) dan memiliki asimtot horizontal y=0.','The basic exponential y=aˣ has a>0, a≠1. Its domain is ℝ and range (0,∞); it passes through (0,1) and has horizontal asymptote y=0.'),
B('Jika a>1, fungsi naik. Jika 0<a<1, fungsi turun. Setiap kenaikan input 1 mengalikan output dengan a, berbeda dengan fungsi linear yang menambah konstanta.','If a>1, the function increases. If 0<a<1, it decreases. Each unit increase in input multiplies the output by a, unlike a linear function which adds a constant.'),
B('e≈2.71828 adalah basis eksponen alami. y=eˣ memiliki sifat dasar domain, range, dan monotonisitas yang sama seperti basis lain yang lebih besar dari 1.','e≈2.71828 is the natural exponential base. y=eˣ has the same basic domain, range and monotonicity properties as other bases greater than 1.')],
'f(x+1)/f(x) = a for f(x)=aˣ',
B('f(x)=(1/2)ˣ turun: f(−1)=2, f(0)=1, f(1)=1/2. Nilainya tidak pernah nol untuk input real berhingga.','f(x)=(1/2)ˣ decreases: f(−1)=2, f(0)=1, f(1)=1/2. It never equals zero for finite real inputs.'),
B('Grafik yang mendekati sumbu-x tidak memotongnya.','Approaching the x-axis does not mean crossing it.'),
B('Bandingkan basis di bawah 1 dan di atas 1. Nilai dan titik (0,1) ditampilkan tepat.','Compare bases below and above 1. Values and the point (0,1) are shown accurately.'),[
R('Intersep-y dari y=5ˣ adalah…','The y-intercept of y=5ˣ is…',['(0,1)','(0,5)','(1,0)','(5,0)'],['Intersep-y memakai x=0.','5⁰=1, jadi titiknya (0,1).'],['At the y-intercept x=0.','5⁰=1, so the point is (0,1).'],'Semua basis positif memberi a⁰=1.','Every positive base satisfies a⁰=1.'),
R('Fungsi mana yang turun pada seluruh ℝ?','Which function decreases throughout ℝ?',['(0.7)ˣ','(1.7)ˣ','eˣ','3ˣ'],['Basis 0.7 berada di antara 0 dan 1.','Pada kenaikan x sebesar 1, output dikali 0.7, sehingga turun.'],['The base 0.7 lies between 0 and 1.','Each unit increase in x multiplies the output by 0.7, so it decreases.'],'Perhatikan basis, bukan koefisien x.','Look at the base.'),
R('Range y=3−2ˣ, x∈ℝ, adalah…','Find the range of y=3−2ˣ for x∈ℝ.',['(−∞,3)','(−∞,3]','(3,∞)','ℝ'],['Karena 2ˣ>0, maka 3−2ˣ<3.','2ˣ mengambil semua nilai positif, sehingga 3−2ˣ mengambil semua nilai di bawah 3, tanpa mencapai 3.'],['Since 2ˣ>0, we have 3−2ˣ<3.','2ˣ takes every positive value, so 3−2ˣ takes every value below 3, without reaching 3.'],'Transformasi range harus menjaga batas terbuka.','Preserve an open boundary when transforming the range.')]),
S(B('Persamaan eksponen','Exponential equations'),[
B('Jika basis positif yang sama bukan 1, aᵘ=aᵛ berarti u=v, karena fungsi eksponen satu-ke-satu. Coba tulis kedua sisi dengan basis yang sama.','For a common positive base other than 1, aᵘ=aᵛ implies u=v because the exponential is one-to-one. Try rewriting both sides with a common base.'),
B('Untuk persamaan yang mengandung a²ˣ dan aˣ, gunakan substitusi t=aˣ>0. Selesaikan kuadrat dalam t lalu kembalikan ke x.','For equations containing a²ˣ and aˣ, use t=aˣ>0. Solve the quadratic in t, then return to x.'),
B('Jika basis tidak dapat disamakan dengan mudah, logaritma memberi x=ln b/ln a untuk aˣ=b, b>0. Metode ini dibahas lebih lanjut pada unit logaritma.','If bases are not easily matched, logarithms give x=ln b/ln a for aˣ=b, b>0. The logarithm unit develops this method.')],
'aᵘ = aᵛ ⇔ u=v (a>0, a≠1)',
B('4ˣ−5·2ˣ+4=0. Ambil t=2ˣ>0, sehingga t²−5t+4=(t−1)(t−4)=0. Maka 2ˣ=1 atau 4, memberi x=0 atau 2.','4ˣ−5·2ˣ+4=0. Let t=2ˣ>0, giving t²−5t+4=(t−1)(t−4)=0. Thus 2ˣ=1 or 4, giving x=0 or 2.'),
B('a²ˣ=(aˣ)², sedangkan a^(x²) memiliki arti berbeda.','a²ˣ=(aˣ)², whereas a^(x²) has a different meaning.'),
B('Ubah titik uji untuk membaca input yang menghasilkan output tertentu; untuk jawaban tepat, gunakan aljabar.','Change the test input to inspect which input gives a target output; use algebra for exact answers.'),[
R('Selesaikan 2ˣ=32.','Solve 2ˣ=32.',['5','4','16','−5'],['32=2⁵.','Karena 2ˣ satu-ke-satu, x=5.'],['32=2⁵.','Since 2ˣ is one-to-one, x=5.'],'Tulis target sebagai pangkat dari basis.','Write the target as a power of the base.'),
R('Selesaikan 9ˣ=27.','Solve 9ˣ=27.',['3/2','2/3','3','1/2'],['9ˣ=3²ˣ dan 27=3³.','2x=3 sehingga x=3/2.'],['9ˣ=3²ˣ and 27=3³.','2x=3, so x=3/2.'],'Ubah keduanya ke basis 3.','Rewrite both sides using base 3.'),
R('Selesaikan 4ˣ−5·2ˣ+4=0.','Solve 4ˣ−5·2ˣ+4=0.',['x=0, 2','x=1, 4','x=0, 4','x=1, 2'],['Ambil t=2ˣ, maka 4ˣ=t².','(t−1)(t−4)=0 memberi t=1 atau 4.','Kembalikan: 2ˣ=1 → x=0; 2ˣ=4 → x=2.'],['Let t=2ˣ, so 4ˣ=t².','(t−1)(t−4)=0 gives t=1 or 4.','Return to x: 2ˣ=1 → x=0; 2ˣ=4 → x=2.'],'Akar persamaan dalam t belum merupakan jawaban x.','Solutions in t are not yet solutions in x.')])]),
U('logarithm',B('Fungsi logaritma','Logarithmic functions'),B('Pertanyaan terbalik: pangkat berapa?','The reverse question: what exponent?'),B('Eksponen dan domain fungsi.','Exponentials and function domains.'),B('Memahami definisi invers, hukum logaritma, serta syarat solusi persamaan.','Understand the inverse definition, logarithm laws, and equation admissibility.'),[
S(B('Definisi & domain','Definition & domain'),[
B('logₐx=y berarti aʸ=x, dengan a>0, a≠1, x>0. Logaritma mengembalikan pangkat, sehingga logₐ adalah invers fungsi eksponen aˣ.','logₐx=y means aʸ=x, with a>0, a≠1, x>0. A logarithm returns an exponent, so logₐ is the inverse of aˣ.'),
B('Domain y=logₐx adalah (0,∞), range ℝ. Grafik melalui (1,0), memiliki asimtot vertikal x=0, dan naik jika a>1 atau turun jika 0<a<1.','The domain of y=logₐx is (0,∞), and its range is ℝ. It passes through (1,0), has vertical asymptote x=0, and increases for a>1 or decreases for 0<a<1.'),
B('ln x berarti logₑx. Untuk logₐ(g(x)) bernilai real, syaratnya g(x)>0, bukan ≥0.','ln x means logₑx. For logₐ(g(x)) to be real, require g(x)>0, not ≥0.')],
'logₐx = y ⇔ aʸ = x',
B('log₂8=3 karena 2³=8; log₂(1/4)=−2 karena 2⁻²=1/4. Domain ln(x−3) adalah x>3.','log₂8=3 because 2³=8; log₂(1/4)=−2 because 2⁻²=1/4. The domain of ln(x−3) is x>3.'),
B('Logaritma boleh bernilai negatif; argumennya harus positif.','A logarithm may be negative; its argument must be positive.'),
B('Tampilkan logₐx dan opsional invers aˣ. Dengan skala sama, kedua kurva direfleksikan terhadap y=x.','Show logₐx and optionally its inverse aˣ. With equal scales, they reflect in y=x.'),[
R('Hitung log₂8.','Evaluate log₂8.',['3','4','2','16'],['Cari pangkat y sehingga 2ʸ=8.','2³=8 sehingga log₂8=3.'],['Find the exponent y for which 2ʸ=8.','2³=8, so log₂8=3.'],'Logaritma menjawab “pangkat berapa”.','A logarithm asks “what exponent”.'),
R('Domain ln(2x−6) adalah…','Find the domain of ln(2x−6).',['x>3','x≥3','x<3','x≠3'],['Argumen harus positif: 2x−6>0.','Maka x>3; logaritma nol tidak terdefinisi.'],['The argument must be positive: 2x−6>0.','Thus x>3; the logarithm of zero is undefined.'],'Log membutuhkan >0, berbeda dari akar kuadrat.','Logs require >0, unlike square roots.'),
R('Domain ln((x−1)(x+2)) adalah…','Find the domain of ln((x−1)(x+2)).',['x<−2 atau / or x>1','−2<x<1','x≠−2, 1','x≥1'],['Syarat (x−1)(x+2)>0.','Akar −2 dan 1 membagi garis bilangan; hasil kali positif di luar kedua akar.','Batas tidak termasuk karena log(0) tidak terdefinisi.'],['Require (x−1)(x+2)>0.','The roots −2 and 1 divide the number line; the product is positive outside them.','Exclude the endpoints because log(0) is undefined.'],'Tidak cukup hanya mengeluarkan akar; tanda argumen juga penting.','Excluding the roots is insufficient; the argument sign matters.')]),
S(B('Hukum & ganti basis','Laws & change of base'),[
B('Untuk u,v>0 dan basis sah: logₐ(uv)=logₐu+logₐv; logₐ(u/v)=logₐu−logₐv; logₐ(uʳ)=r logₐu. Hukum ini berasal dari hukum eksponen.','For u,v>0 and a valid base: logₐ(uv)=logₐu+logₐv; logₐ(u/v)=logₐu−logₐv; logₐ(uʳ)=r logₐu. These follow from the index laws.'),
B('Ganti basis: logₐx=ln x/ln a. Kalkulator dapat memakai ln atau log basis 10; pembilang dan penyebut harus memakai basis yang sama.','Change of base: logₐx=ln x/ln a. A calculator may use ln or base-10 log; numerator and denominator must use the same base.'),
B('Tidak ada aturan log(u+v)=log u+log v. Juga, ln(x²)=2ln|x| untuk x≠0; penulisan 2ln x hanya sah jika x>0.','There is no law log(u+v)=log u+log v. Also, ln(x²)=2ln|x| for x≠0; writing 2ln x is valid only for x>0.')],
'logₐx = ln x / ln a',
B('log₂12−log₂3=log₂4=2. Untuk x≠0, ln(x²) mengambil argumen positif walaupun x negatif, sehingga bentuk umum adalah 2ln|x|.','log₂12−log₂3=log₂4=2. For x≠0, ln(x²) has a positive argument even when x is negative, so the general form is 2ln|x|.'),
B('Pastikan argumen tiap log positif sebelum memisahkan atau menggabungkan.','Check that each log argument is positive before splitting or combining.'),
B('Geser t>0. Panel menghitung logₐt, lalu memeriksa identitas logₐ(t²)=2logₐt secara numerik.','Vary t>0. The panel evaluates logₐt and checks logₐ(t²)=2logₐt numerically.'),[
R('log₃9+log₃3 sama dengan…','Evaluate log₃9+log₃3.',['3','2','4','log₃12'],['log₃9=2 dan log₃3=1.','Jumlahnya 3; atau log₃(9×3)=log₃27=3.'],['log₃9=2 and log₃3=1.','The sum is 3; alternatively log₃(9×3)=log₃27=3.'],'Penjumlahan log menggabungkan perkalian argumen.','Adding logs corresponds to multiplying arguments.'),
R('Nilai ln 25 / ln 5 adalah…','Evaluate ln 25 / ln 5.',['2','5','ln 20','1/2'],['Ganti basis: ln25/ln5=log₅25.','Karena 5²=25, nilainya 2.'],['By change of base, ln25/ln5=log₅25.','Since 5²=25, the value is 2.'],'Rasio log adalah log dengan basis baru.','A ratio of logs can express a new base.'),
R('Bentuk yang sama dengan ln(x²) untuk semua x≠0 adalah…','Which equals ln(x²) for every x≠0?',['2ln|x|','2ln x','(ln x)²','ln(2x)'],['Karena |x|>0, ln(|x|²)=2ln|x|.','x²=|x|², sehingga bentuk itu berlaku juga untuk x negatif.'],['Since |x|>0, ln(|x|²)=2ln|x|.','x²=|x|², so this also works for negative x.'],'2ln x tidak terdefinisi pada x negatif.','2ln x is undefined for negative x.')]),
S(B('Persamaan & syarat solusi','Equations & admissibility'),[
B('Catat domain setiap log terlebih dahulu. Dengan basis sah yang sama, logₐu=logₐv berarti u=v asalkan u,v>0.','First record the domain of each logarithm. For the same valid base, logₐu=logₐv implies u=v provided u,v>0.'),
B('Gabungkan log, ubah ke bentuk eksponen, selesaikan aljabar, lalu uji kembali semua calon solusi. Penggabungan tidak boleh memperluas domain soal awal.','Combine logs, rewrite exponentially, solve algebraically, then test every candidate. Combining logs must not expand the original domain.'),
B('Untuk aˣ=b dengan a>0, a≠1 dan b>0: ambil ln kedua sisi, x ln a=ln b. Untuk pertidaksamaan log basis di bawah 1, fungsi turun sehingga arah pertidaksamaan berbalik.','For aˣ=b with a>0, a≠1 and b>0: take ln of both sides, giving x ln a=ln b. For log inequalities with base below 1, the function is decreasing, so the inequality reverses.')],
'aˣ=b ⇒ x=ln b / ln a (b>0)',
B('log₂(x−1)+log₂(x+1)=3. Domain x>1. Gabungkan: x²−1=8 → x=±3. Hanya x=3 memenuhi domain.','log₂(x−1)+log₂(x+1)=3. The domain is x>1. Combine: x²−1=8 → x=±3. Only x=3 meets the domain.'),
B('Akar persamaan polinom hasil penggabungan dapat tidak sah untuk persamaan log awal.','A root of the resulting polynomial may be inadmissible in the original log equation.'),
B('Gunakan grafik untuk menafsirkan log sebagai input balik; perhitungan tepat tetap memakai identitas dan syarat domain.','Use the graph to interpret a log as a reverse input; exact work still uses identities and domain conditions.'),[
R('Selesaikan log₂x=4.','Solve log₂x=4.',['16','8','2','1/16'],['Bentuk eksponen: x=2⁴.','x=16>0 sehingga sah.'],['Rewrite exponentially: x=2⁴.','x=16>0, so it is valid.'],'Periksa basis dan pangkat.','Identify the base and exponent.'),
R('Selesaikan ln(x−1)=ln 3.','Solve ln(x−1)=ln 3.',['4','2','3','e³+1'],['Domain x>1. Karena ln satu-ke-satu, x−1=3.','x=4 memenuhi domain.'],['The domain is x>1. Since ln is one-to-one, x−1=3.','x=4 meets the domain.'],'Log yang sama dapat dibandingkan melalui argumennya.','Equal logs with the same base have equal arguments.'),
R('Selesaikan log₂(x−1)+log₂(x+1)=3.','Solve log₂(x−1)+log₂(x+1)=3.',['x=3','x=−3, 3','x=−3','x=9'],['Domain awal: x−1>0 dan x+1>0, jadi x>1.','log₂((x−1)(x+1))=3 → x²−1=8 → x=±3.','Buang x=−3; kedua argumen awal negatif. Solusinya x=3.'],['Original domain: x−1>0 and x+1>0, so x>1.','log₂((x−1)(x+1))=3 → x²−1=8 → x=±3.','Reject x=−3 because both original arguments are negative. The solution is x=3.'],'Domain persamaan awal tetap menjadi syarat akhir.','The original domain remains a final condition.')])]),
U('modelling',B('Pemodelan & sintesis','Modelling & synthesis'),B('Hubungkan aturan, konteks, satuan, dan batas model.','Connect rules, context, units, and model limits.'),B('Eksponen, logaritma, invers, dan komposisi.','Exponentials, logarithms, inverses, and composition.'),B('Membangun model pertumbuhan dan peluruhan serta menafsirkan jawaban dalam konteks.','Build growth and decay models and interpret answers in context.'),[
S(B('Pertumbuhan per periode','Growth per period'),[
B('Jika kuantitas bertambah p bagian dari nilainya setiap periode, modelnya Nₙ=N₀(1+p)ⁿ. Untuk penurunan p dengan 0<p<1, gunakan faktor 1−p.','If a quantity increases by proportion p of its current value each period, Nₙ=N₀(1+p)ⁿ. For a decrease p with 0<p<1, use factor 1−p.'),
B('n adalah jumlah periode, biasanya bilangan bulat tidak negatif. Pertumbuhan 5% berarti faktor 1.05, bukan 0.05. Pastikan satuan waktu konsisten.','n counts periods, usually nonnegative integers. Growth of 5% gives factor 1.05, not 0.05. Keep time units consistent.'),
B('Pada pertanyaan “periode pertama mencapai target”, selesaikan batas real lalu pilih bilangan bulat pertama yang memenuhi. Model mengasumsikan persentase tetap dan mengabaikan batas sumber daya.','For “the first period to reach a target”, solve the real threshold then choose the first integer satisfying it. The model assumes a constant percentage and ignores resource limits.')],
'Nₙ = N₀qⁿ, n=0,1,2,…',
B('100 unit tumbuh 20% per periode: Nₙ=100(1.2)ⁿ. Untuk Nₙ≥150: n≥ln1.5/ln1.2≈2.224. Periode pertama n=3; cek N₂=144<150 dan N₃=172.8≥150.','100 units grow by 20% per period: Nₙ=100(1.2)ⁿ. For Nₙ≥150: n≥ln1.5/ln1.2≈2.224. The first period is n=3; check N₂=144<150 and N₃=172.8≥150.'),
B('Nilai n pecahan pada kurva perpanjangan bukan periode diskret yang sebenarnya.','A fractional n on an interpolating curve is not an actual discrete period.'),
B('Titik menandai model diskret Nₙ/N₀=qⁿ pada n bulat. Garis putus-putus hanya perpanjangan real.','Points mark the discrete model Nₙ/N₀=qⁿ at integer n. The dashed line is only a real-valued extension.'),[
R('200 tumbuh 10% selama satu periode. Nilai akhirnya…','200 grows by 10% for one period. The final value is…',['220','210','20','2000'],['Faktor pengali 1+0.10=1.10.','200×1.10=220.'],['The multiplier is 1+0.10=1.10.','200×1.10=220.'],'Persentase perubahan bukan faktor akhir.','The percentage change is not the final multiplier.'),
R('Nilai awal 500 turun 20% tiap tahun. Setelah 2 tahun…','An initial value of 500 decreases by 20% each year. After 2 years it is…',['320','300','400','200'],['Faktor tahunan 0.8.','500×0.8²=500×0.64=320.'],['The annual multiplier is 0.8.','500×0.8²=500×0.64=320.'],'Penurunan tahun kedua diterapkan pada nilai yang sudah berubah.','The second decrease acts on the updated value.'),
R('100 tumbuh 20% tiap periode. Periode bulat pertama mencapai minimal 150 adalah…','100 grows by 20% per period. The first integer period reaching at least 150 is…',['3','2','2.224','4'],['100(1.2)ⁿ≥150 memberi n≥ln1.5/ln1.2≈2.224.','Pilih bilangan bulat pertama n=3. Cek n=2 menghasilkan 144 dan n=3 menghasilkan 172.8.'],['100(1.2)ⁿ≥150 gives n≥ln1.5/ln1.2≈2.224.','Choose the first integer n=3. Check: n=2 gives 144; n=3 gives 172.8.'],'Pembulatan ke bilangan terdekat tidak menjawab “periode pertama”.','Rounding to the nearest integer does not answer “first period”.')]),
S(B('Model kontinu & invers','Continuous models & inverses'),[
B('Model kontinu N(t)=N₀eᵏᵗ memakai t≥0. k memiliki satuan kebalikan waktu: positif untuk pertumbuhan, negatif untuk peluruhan. Nilai model dapat real meskipun kuantitas aktual dibulatkan saat diamati.','The continuous model N(t)=N₀eᵏᵗ uses t≥0. k has units of inverse time: positive for growth, negative for decay. Model values may be real even when observed quantities are rounded.'),
B('Waktu mencapai target M>0 diperoleh dari invers: t=ln(M/N₀)/k untuk k≠0. Periksa apakah t≥0; target yang bertentangan dengan arah pertumbuhan tidak tercapai di masa depan.','Time to reach a positive target M comes from the inverse: t=ln(M/N₀)/k for k≠0. Check t≥0; a target against the growth direction is not reached in the future.'),
B('Waktu paruh H pada peluruhan memberi k=−ln2/H; waktu penggandaan T pada pertumbuhan memberi k=ln2/T. Model eksponen tidak otomatis merupakan hukum yang valid selamanya.','A decay half-life H gives k=−ln2/H; a growth doubling time T gives k=ln2/T. An exponential model is not automatically a law valid forever.')],
'N(t)=N₀eᵏᵗ; t=ln(M/N₀)/k (k≠0)',
B('N(0)=80 dan N(3)=40 memberi k=−ln2/3 per jam. N(t)=80e^(−t ln2/3). Target 20 tercapai setelah dua waktu paruh, t=6 jam.','N(0)=80 and N(3)=40 give k=−ln2/3 per hour. N(t)=80e^(−t ln2/3). A target of 20 is reached after two half-lives, t=6 hours.'),
B('k=0.05 per tahun bukan persis pertumbuhan 5% per tahun; faktor satu tahunnya e^0.05.','k=0.05 per year is not exactly 5% annual growth; its one-year factor is e^0.05.'),
B('Grafik memakai rasio N(t)/N₀=eᵏᵗ sehingga sumbu dan satuan jelas. Ubah k dan waktu t; model hanya digambar untuk t≥0.','The graph uses the ratio N(t)/N₀=eᵏᵗ so axes and units stay clear. Vary k and time t; only t≥0 is plotted.'),[
R('Pada N(t)=100e^(−0.2t), nilai awalnya…','For N(t)=100e^(−0.2t), the initial value is…',['100','−0.2','0','e¹⁰⁰'],['Nilai awal memakai t=0.','N(0)=100e⁰=100.'],['The initial value is at t=0.','N(0)=100e⁰=100.'],'Koefisien di depan eksponen adalah N₀.','The coefficient in front of the exponential is N₀.'),
R('Waktu paruh 3 jam, nilai awal 80. Kapan nilai menjadi 20?','The half-life is 3 hours and the initial value is 80. When does it reach 20?',[B('6 jam','6 hours'),B('3 jam','3 hours'),B('9 jam','9 hours'),B('12 jam','12 hours')],['80→40→20 membutuhkan dua waktu paruh.','Dua kali 3 jam adalah 6 jam.'],['80→40→20 takes two half-lives.','Two times 3 hours is 6 hours.'],'Setiap waktu paruh membagi dua nilai saat itu.','Each half-life halves the current value.'),
R('N(t)=100e^(0.2t), t≥0. Kapan model mencapai 50?','N(t)=100e^(0.2t), t≥0. When does the model reach 50?',[B('Tidak tercapai untuk t≥0','Not reached for t≥0'),'t=ln2/0.2','t=0.2ln2','t=5'],['Invers memberi t=ln(0.5)/0.2<0.','Nilai itu di luar domain waktu. Untuk t≥0, N(t)≥100 sehingga 50 tidak tercapai.'],['The inverse gives t=ln(0.5)/0.2<0.','That is outside the time domain. For t≥0, N(t)≥100, so 50 is not reached.'],'Jawaban aljabar harus memenuhi domain konteks.','An algebraic answer must satisfy the contextual domain.')])])
);
// Deterministic answer ordering; legacy questions retain their existing keys.
units.slice(6).forEach((u,i)=>u.subtopics.forEach((s,j)=>s.questions.forEach((q,k)=>{const shift=(i+j+k+1)%q.options.length;q.options=q.options.slice(shift).concat(q.options.slice(0,shift));q.correct=(q.correct-shift+q.options.length)%q.options.length})));
